import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-arp-session-details',
  templateUrl: './arp-session-details.page.html',
  styleUrls: ['./arp-session-details.page.scss'],
})
export class ArpSessionDetailsPage implements OnInit {
  dataParam: any;
  studentDetails: any;

  constructor(public router:Router,private userSessionService: UserSessionService,private route: ActivatedRoute) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.route.queryParams.subscribe((params) => {
      this.dataParam = JSON.parse(params['data']);
      this.studentDetails = this.dataParam.students_list
    })
  }

  backBtn(){
    this.router.navigate(["/tabs/ka-session-verification"])
  }
}
